(ns vtranslate.cli.schema
  "CLI-owned data contracts. Open extension maps reflect provider/addon plugins."
  (:require [vtranslate.cli.job-spec :as spec]
            [vtranslate.cli.web.schema :as web]))
(def JobSpec spec/JobSpec)
(def SubmitRequest web/SubmitRequest)
(def Job web/Job)
(def ConfigPatch web/ConfigPatch)
(def Port [:enum :transcriber :translator :comprehender :composer])
(def ProviderOptions [:map [:secret-pass {:optional true} :string] [:model {:optional true} :string] [:model-path {:optional true} :string] [:threads {:optional true} [:or :int [:= :auto]]]])
(def Provider [:map [:offline {:optional true} :boolean] [:api-url {:optional true} :string] [:binary {:optional true} :string] [:secret-env {:optional true} :string] [:default-model {:optional true} :string] [:note {:optional true} :string]])
(def Config [:map [:providers {:optional true} [:map-of Port :keyword]] [:registry {:optional true} [:map-of Port [:map-of :keyword Provider]]] [:addons {:optional true} [:vector [:or :keyword :map]]] [:transcriber-opts {:optional true} ProviderOptions] [:translator-opts {:optional true} ProviderOptions] [:comprehender-opts {:optional true} ProviderOptions]])
(def ClasspathPreset [:map [:extra-paths {:optional true} [:vector :string]] [:extra-deps {:optional true} :map]])
(def LocalDeps [:map [:vtranslate.cli/addon-aliases {:optional true} [:map-of :keyword [:vector :keyword]]] [:aliases {:optional true} [:map-of :keyword ClasspathPreset]]])
(def Invocation [:map [:dir [:maybe :string]] [:command [:vector :string]]])
(def ProcessResult [:map [:exit :int] [:out :string] [:err :string]])
(def Result [:or [:map [:ok :any]] [:map [:error :keyword]]])
(def Route [:maybe [:map [:action :keyword] [:params [:map [:id {:optional true} :string]]]]])
(def DialogOptions [:map [:title {:optional true} [:maybe :string]] [:dir {:optional true} [:maybe :string]]])
(def Dialog [:map [:id :keyword] [:binary :string] [:argv ifn?]])
(def Summary [:map [:output {:optional true} :string] [:job {:optional true} :map] [:output-video {:optional true} :string] [:outputs {:optional true} [:vector [:map [:language :string] [:output :string]]]]])
(def Store [:map [:jobs [:map-of :string Job]] [:order [:vector :string]]])
(def JobView [:map [:id :string] [:status web/JobStatus] [:request SubmitRequest] [:log :string] [:duration-ms [:maybe :int]] [:error [:maybe :string]]])
(def Diagnostic [:map [:port Port] [:active [:maybe :keyword]] [:known [:vector :keyword]] [:configured? :boolean] [:offline? :boolean] [:secret-source [:maybe [:enum :pass :env]]] [:secret-set? [:maybe :boolean]] [:opts [:maybe ProviderOptions]]])
(def DoctorReport [:map [:config-path :string] [:addons [:maybe [:vector [:or :keyword :map]]]] [:providers [:vector Diagnostic]]])
(def HTTPResponse [:map [:status :int] [:headers {:optional true} [:map-of :string :string]] [:body :any]])
